// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint96).max);
        address payable receiver = payable(address(uint160(uint256(keccak256(abi.encode(amount))))));
        vm.assume(receiver != address(0));
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {} catch {}
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore - balanceAfter == amount);
    }
}
